:root {
  --color-primary: #2563eb;
  --button-bg: var(--color-primary);   /* freezes here = #2563eb */
}
[data-theme="dark"] {
  --color-primary: #60a5fa;
  /* --button-bg NOT re-declared → inherits #2563eb from :root */
}
/* .btn--primary { background: var(--button-bg); } → #2563eb in dark mode (BUG) */

cases.good:
/* tokens.css */
:root {
  --color-primary: #2563eb;
  --button-bg: var(--color-primary);
}
[data-theme="dark"] {
  --color-primary: #60a5fa;
  --button-bg: var(--color-primary);   /* re-resolves here = #60a5fa */
}
/* .btn--primary { background: var(--button-bg); } → #60a5fa in dark mode (CORRECT) */

